    )
    $names = @('PASSKEY_PRIVATE_CREDENTIAL_ID','PASSKEY_PRIVATE_USER_HANDLE','PASSKEY_PRIVATE_USER_PRINCIPAL_NAME','PASSKEY_PRIVATE_KEY')
    $confirmed = @($ConfirmedWrites | Where-Object { $_ -cin $names })
    $code = "Passkey$($Stage)Failed"
